class Solution {
  public int bitRibbonsPositiveInkInvoice(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){int count=0;while(x!=0){x&=x-1;count++;}out.add(count);}}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
